    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    ink = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]

    # Locate the outlined cavity: paired vertical sides beneath a full top edge.
    candidates = []
    for left in range(w):
        for right in range(left + 2, w):
            for top in range(h):
                if not all(grid[top][c] == ink for c in range(left, right + 1)):
                    continue
                bottom = top + 1
                while (bottom < h and grid[bottom][left] == ink
                       and grid[bottom][right] == ink):
                    bottom += 1
                depth = bottom - top - 1
                if depth > 0:
                    candidates.append((depth * (right-left-1), left, right, top, bottom))

    if candidates:
        _, left, right, top, bottom = max(candidates)
        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                if grid[r][c] == bg:
                    out[r][c] = 4
    return out
